  downloadURLs.push(png, json);
  status.replaceChildren(
    el("a", { className: "btn", href: png, download: `${name}.png`, textContent: "\uC7A5\uBA74 PNG \uB2E4\uC6B4\uB85C\uB4DC" }),
    " ",
    el("a", { className: "btn", href: json, download: `${name}.json`, textContent: "\uC7A5\uBA74 JSON \uB2E4\uC6B4\uB85C\uB4DC" })
  );
